#include <stdio.h>

// Iterative Linear Search
int linearSearch(int arr[], int n, int key) {
    for (int i = 0; i < n; i++) {
        if (arr[i] == key) {
            return i; // Element found at index i
        }
    }
    return -1; // Element not found
}

// Recursive Linear Search
int linearSearchRecursive(int arr[], int n, int key, int index) {
    if (index >= n) return -1; // Base case: element absent
    if (arr[index] == key) return index; // Base case: match found
    return linearSearchRecursive(arr, n, key, index + 1); // Recursive call
}

int main(void) {
    int arr[] = {10, 25, 45, 60, 75};
    int n = sizeof(arr) / sizeof(arr[0]);
    int key = 60;

    printf("--- Linear Search in C ---\n");
    printf("Array elements: ");
    for (int i = 0; i < n; i++) printf("%d ", arr[i]);
    printf("\nSearching for key: %d\n", key);

    int result = linearSearch(arr, n, key);
    if (result != -1) {
        printf("Element %d found at index %d (Position %d).\n", key, result, result + 1);
    } else {
        printf("Element %d not found in the array.\n", key);
    }
    return 0;
}

#include <stdio.h>

// Iterative Binary Search
int binarySearch(int arr[], int n, int key) {
    int low = 0;
    int high = n - 1;
    while (low <= high) {
        // Prevents integer overflow compared to (low + high) / 2
        int mid = low + (high - low) / 2;
        if (arr[mid] == key) {
            return mid; // Key found
        } else if (arr[mid] < key) {
            low = mid + 1; // Discard left half
        } else {
            high = mid - 1; // Discard right half
        }
    }
    return -1; // Key absent
}

// Recursive Binary Search
int binarySearchRecursive(int arr[], int low, int high, int key) {
    if (low > high) return -1; // Base case: absent
    int mid = low + (high - low) / 2;
    if (arr[mid] == key) return mid;
    if (arr[mid] < key) return binarySearchRecursive(arr, mid + 1, high, key);
    return binarySearchRecursive(arr, low, mid - 1, key);
}

int main(void) {
    int arr[] = {11, 22, 33, 44, 55, 66, 77};
    int n = sizeof(arr) / sizeof(arr[0]);
    int key = 55;

    printf("--- Binary Search in C ---\n");
    printf("Sorted Array: ");
    for (int i = 0; i < n; i++) printf("%d ", arr[i]);
    printf("\nSearching for key: %d\n", key);

    int result = binarySearch(arr, n, key);
    if (result != -1) {
        printf("Element %d found at index %d (Position %d).\n", key, result, result + 1);
    } else {
        printf("Element %d not found in the array.\n", key);
    }
    return 0;
}
